def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    zero_rows, zero_cols = set(), set()
    for r in range(h-1):
        for c in range(w-1):
            if all(grid[rr][cc] == 0 for rr in (r, r+1) for cc in (c, c+1)):
                zero_rows.update((r, r+1))
                zero_cols.update((c, c+1))
    for r in zero_rows:
        for c in range(w):
            if out[r][c] != 2: out[r][c] = 0
    for c in zero_cols:
        for r in range(h):
            if out[r][c] != 2: out[r][c] = 0
    return out
